pre:
# CCleaner custom-include setup (runs in its own scope).
& {
  $reg = 'HKCU:\Software\Piriform\CCleaner'
  if (-not (Test-Path $reg)) { New-Item -Path $reg -Force | Out-Null }
  $n = 0
  Get-ChildItem -LiteralPath '{dir}' -File | Sort-Object Name | Select-Object -First 40 | ForEach-Object {
    $n++
    Set-ItemProperty -Path $reg -Name ("Include" + $n) -Value ("FILE|{dir}\|" + $_.Name)
  }
  Set-ItemProperty -Path $reg -Name '(App)Custom Files' -Value 'True'
  Set-ItemProperty -Path $reg -Name '(App)Custom Folders' -Value 'True'
  Set-ItemProperty -Path $reg -Name 'SecureDeleteType' -Value '1' -Type String
  Set-ItemProperty -Path $reg -Name 'SecureDeleteMethod' -Value '0' -Type String
  Set-ItemProperty -Path $reg -Name 'UpdateBackgroundCheck' -Value '0' -Type String
  Set-ItemProperty -Path $reg -Name 'MSG_CONFIRMCLEAN' -Value 'False'
}
